import React, { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { ArrowRight, Play, Star } from 'lucide-react';
import { STOCK_TICKERS } from '../constants';

gsap.registerPlugin(ScrollTrigger);

const Hero: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const subRef = useRef<HTMLParagraphElement>(null);
  const videoRef = useRef<HTMLDivElement>(null);
  const tickerRef = useRef<HTMLDivElement>(null);
  const [timeLeft, setTimeLeft] = useState('23:59:59');

  useEffect(() => {
    // Countdown Logic
    const timer = setInterval(() => {
      const date = new Date();
      const hours = 23 - date.getHours();
      const minutes = 59 - date.getMinutes();
      const seconds = 59 - date.getSeconds();
      setTimeLeft(
        `${hours.toString().padStart(2, '0')}:${minutes
          .toString()
          .padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
      );
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const ctx = gsap.context(() => {
      // Timeline for initial load
      const tl = gsap.timeline();

      tl.fromTo(
        headlineRef.current,
        { y: 100, opacity: 0, rotateX: 10 },
        { y: 0, opacity: 1, rotateX: 0, duration: 1.2, ease: 'power4.out' }
      )
        .fromTo(
          subRef.current,
          { y: 30, opacity: 0 },
          { y: 0, opacity: 1, duration: 0.8, ease: 'power2.out' },
          '-=0.8'
        )
        .fromTo(
          '.hero-btn',
          { y: 20, opacity: 0 },
          { y: 0, opacity: 1, stagger: 0.1, duration: 0.6, ease: 'back.out(1.7)' },
          '-=0.6'
        )
        .fromTo(
          videoRef.current,
          { scale: 0.9, opacity: 0, y: 50 },
          { scale: 1, opacity: 1, y: 0, duration: 1, ease: 'power3.out' },
          '-=0.4'
        )
        .fromTo(
          tickerRef.current,
          { opacity: 0 },
          { opacity: 1, duration: 1 },
          '-=0.5'
        );

      // Parallax effect on scroll
      gsap.to('.hero-bg-gradient', {
        yPercent: 30,
        ease: 'none',
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top top',
          end: 'bottom top',
          scrub: true,
        },
      });

      // Ticker Animation
      gsap.to('.ticker-track', {
        xPercent: -50,
        repeat: -1,
        duration: 20,
        ease: 'linear',
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

  return (
    <div ref={containerRef} className="relative min-h-screen flex flex-col pt-20 overflow-hidden bg-brand-black">
      {/* Background Effects */}
      <div className="absolute inset-0 z-0 opacity-40 pointer-events-none">
        <div className="hero-bg-gradient absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-brand-blue rounded-full blur-[150px] opacity-20" />
        <div className="hero-bg-gradient absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-900 rounded-full blur-[120px] opacity-20" />
      </div>

      {/* Urgency Bar */}
      <div className="w-full bg-brand-blue/10 border-b border-brand-blue/20 backdrop-blur-md py-2 flex justify-center items-center gap-3 z-50 fixed top-0 left-0">
        <span className="text-brand-blue text-sm font-semibold animate-pulse">🚀 Limited Seats</span>
        <span className="text-gray-300 text-xs md:text-sm">Enrollment closes in <span className="font-mono font-bold text-white">{timeLeft}</span></span>
      </div>

      <div className="container mx-auto px-4 lg:px-8 flex flex-col items-center justify-center flex-grow z-10 mt-10">
        {/* Content */}
        <div className="max-w-4xl mx-auto text-center space-y-8">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-sm text-gray-300 mb-4 backdrop-blur-sm">
            <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
            1,500+ Successful Students
          </div>

          <h1 ref={headlineRef} className="font-serif text-5xl md:text-7xl lg:text-8xl leading-[1.1] text-transparent bg-clip-text bg-gradient-to-b from-white to-gray-400 italic">
            Master the Colombo <br />
            <span className="not-italic text-white">Stock Exchange</span>
          </h1>

          <p ref={subRef} className="text-lg md:text-xl text-gray-400 max-w-2xl mx-auto font-sans leading-relaxed">
            Learn proven trading strategies from <span className="text-brand-blue font-semibold">Renzo</span>.
            Build real wealth in Sri Lanka with technical analysis and disciplined risk management.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-4">
            <button className="hero-btn group relative px-8 py-4 bg-brand-blue text-white font-semibold rounded-full overflow-hidden hover:shadow-[0_0_30px_-5px_rgba(33,101,252,0.6)] transition-all duration-300">
              <span className="relative z-10 flex items-center gap-2">
                Enroll in the Course <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </span>
              <div className="absolute inset-0 bg-gradient-to-r from-blue-600 to-brand-blue opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
            </button>
            <button className="hero-btn flex items-center gap-2 px-8 py-4 border border-white/20 rounded-full text-white hover:bg-white/5 transition-colors font-medium backdrop-blur-sm">
              <Play className="w-5 h-5 fill-white" /> Watch Free Masterclass
            </button>
          </div>

          <div className="hero-btn flex items-center justify-center gap-6 text-sm text-gray-500 pt-6">
            <div className="flex items-center gap-1">
              <div className="flex">
                {[1, 2, 3, 4, 5].map((i) => (
                  <Star key={i} className="w-4 h-4 fill-yellow-500 text-yellow-500" />
                ))}
              </div>
              <span className="text-gray-300 ml-1">4.9/5 Rating</span>
            </div>
            <span className="hidden sm:inline w-1 h-1 bg-gray-600 rounded-full"></span>
            <div className="flex items-center gap-2">
               <ShieldCheck className="w-4 h-4 text-brand-blue" />
               <span className="text-gray-300">100% Money-Back Guarantee</span>
            </div>
          </div>
        </div>

        {/* Video Placeholder */}
        <div ref={videoRef} className="mt-16 w-full max-w-5xl relative group">
          <div className="absolute -inset-1 bg-gradient-to-r from-brand-blue to-purple-600 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
          <div className="relative aspect-video rounded-2xl bg-gray-900 border border-white/10 overflow-hidden flex items-center justify-center shadow-2xl">
            <img 
              src="https://picsum.photos/1200/675?grayscale" 
              alt="Course Intro" 
              className="absolute inset-0 w-full h-full object-cover opacity-60 mix-blend-overlay"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-brand-black via-transparent to-transparent"></div>

            <button className="relative z-10 w-20 h-20 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center border border-white/20 group-hover:scale-110 transition-transform duration-300 group-hover:bg-brand-blue/20">
               <Play className="w-8 h-8 fill-white text-white ml-1" />
            </button>
          </div>
        </div>
      </div>

      {/* Floating Stock Ticker */}
      <div ref={tickerRef} className="w-full bg-brand-black/80 backdrop-blur-md border-y border-white/5 mt-20 py-4 overflow-hidden relative z-20">
        <div className="ticker-track flex whitespace-nowrap gap-12 w-max">
          {[...STOCK_TICKERS, ...STOCK_TICKERS, ...STOCK_TICKERS].map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-lg font-mono">
              <span className="text-white font-bold">{stock.symbol}</span>
              <span className={stock.change.startsWith('+') ? 'text-green-500' : 'text-red-500'}>
                {stock.change}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Helper Icon for hero
function ShieldCheck({ className }: { className?: string }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/><path d="m9 12 2 2 4-4"/></svg>
  );
}

export default Hero;

