                stagger: 0.2,
                duration: 0.8,
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: certificateRef.current,
                    start: 'top 70%',
                }
            });
        }

        // 5. Bonuses Animation
        if (bonusRef.current) {
            gsap.from('.bonus-card', {
